    },
    {
      "claim_id": "C3",
      "text": "Noninterest expense increased by 4.36% from $66,812 million in 2024 to $69,727 million in 2025.",
      "evidence_ids": [
        "EP_0004_E01"
      ],
      "check_spec": {
        "kind": "percentage_change",
        "from_fact_id": "EP_0004_F06",
        "to_fact_id": "EP_0004_F05",
        "metric": "noninterest_expense",
        "from_period": {
          "label": "FY2024",
          "start": "2024-01-01",
          "end": "2024-12-31"
        },
        "to_period": {
          "label": "FY2025",
          "start": "2025-01-01",
          "end": "2025-12-31"
        },
        "value": "4.36",
        "unit": "percent"
      }
    },
    {
      "claim_id": "C5",
      "text": "The company faces risks from global uncertainties regarding fiscal and monetary policies, including potential interest rate volatility and adverse economic outcomes due to high and rising debt levels, as detailed in Item 1A.",
      "evidence_ids": [
        "EP_0004_E03"
      ],
      "check_spec": null
    }
  ],
  "rationale": "The company demonstrated strong financial performance in 2025, with significant increases in total revenue, net of interest expense, and net income. Diluted earnings per share also saw a notable rise. However, noninterest expense increased, and the company acknowledges material risks related to global economic uncertainties, including interest rate volatility and potential adverse economic outcomes from high debt levels. These risks could negatively impact future net interest income and noninterest income. Given the positive financial performance but also the identified macroeconomic risks, a HOLD recommendation is appropriate."
}

